function avatarSVG(id, size){
  size = size || 100;
  var b = AVATAR_ART[id];
  if(!id || !b) return null;
  var u = 'av' + (avatarSVG._n = (avatarSVG._n || 0) + 1);
  return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 100 100" '
    + 'xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">'
    + '<defs><clipPath id="clip_'+u+'"><circle cx="50" cy="50" r="50"/></clipPath></defs>'
    + '<image clip-path="url(#clip_'+u+')" x="0" y="0" width="100" height="100" '
    + 'preserveAspectRatio="xMidYMid slice" xlink:href="data:image/jpeg;base64,'+b+'"/>'
    + '</svg>';
}
function avatarName(id){ var a=AVATAR_LIST.find(function(x){return x.id===id;}); return a?a.name:''; }
